/**
 * Session store.
 *
 * Maps opaque cookie IDs to a small record. The cookie value is generated by
 * crypto.randomUUID — 122 bits of entropy is sufficient for unguessability.
 *
 * With a file path the sessions survive a restart: a deploy no longer logs
 * the user out, and plugins (loaded before the login dialog, behind the
 * session-guarded plugin proxies) no longer fail on the first page load
 * after one. The file holds SHA-256 hashes of the session IDs, so reading it
 * does not yield a usable cookie. Without a path the store is memory-only.
 */

import { createHash, randomUUID } from "node:crypto";
import { mkdirSync, readFileSync, renameSync, writeFileSync } from "node:fs";
import { dirname } from "node:path";

export interface SessionRecord {
  username: string;
  createdAt: number;
  expiresAt: number;
}

const hashId = (id: string): string => createHash("sha256").update(id).digest("hex");

export class SessionStore {
  /** Keyed by the SHA-256 hash of the session ID. */
  private readonly sessions = new Map<string, SessionRecord>();

  constructor(
    private readonly ttlSeconds: number,
    private readonly path?: string,
  ) {
    if (path) {
      mkdirSync(dirname(path), { recursive: true });
      this.load(path);
    }
  }

  private load(path: string): void {
    let stored: Record<string, SessionRecord>;
    try {
      stored = JSON.parse(readFileSync(path, "utf8")) as Record<string, SessionRecord>;
    } catch (err) {
      // First start: no file yet.
      if ((err as NodeJS.ErrnoException).code === "ENOENT") return;
      throw err;
    }
    const now = Date.now();
    for (const [hash, record] of Object.entries(stored)) {
      if (record.expiresAt > now) this.sessions.set(hash, record);
    }
  }

  private persist(): void {
    if (!this.path) return;
    // Write-then-rename: a crash mid-write cannot leave a truncated file.
    const tmp = `${this.path}.tmp`;
    writeFileSync(tmp, JSON.stringify(Object.fromEntries(this.sessions)), {
      encoding: "utf8",
      mode: 0o600,
    });
    renameSync(tmp, this.path);
  }

  create(username: string): string {
    const id = randomUUID();
    const now = Date.now();
    // Expired sessions were only dropped when looked up again, and every
    // clipper login creates one that is never looked up.
    for (const [hash, record] of this.sessions) {
      if (record.expiresAt <= now) this.sessions.delete(hash);
    }
    this.sessions.set(hashId(id), {
      username,
      createdAt: now,
      expiresAt: now + this.ttlSeconds * 1000,
    });
    this.persist();
    return id;
  }

  lookup(id: string): SessionRecord | undefined {
    const hash = hashId(id);
    const record = this.sessions.get(hash);
    if (!record) return undefined;
    if (record.expiresAt <= Date.now()) {
      this.sessions.delete(hash);
      this.persist();
      return undefined;
    }
    return record;
  }

  delete(id: string): void {
    if (this.sessions.delete(hashId(id))) this.persist();
  }
}

export const SESSION_COOKIE_NAME = "hypha-session";
